def augmented_seg_predict(grid, wallval, components, marklabels):
 h=len(grid);w=len(grid[0]);W={(r,c) for r in range(h) for c in range(w) if grid[r][c]==wallval};adj=adj4
 # seed labels by cardinal adjacency to labeled marker components
 src=defaultdict(set)
 for p in W:
  for dr,dc in adj:
   z=(p[0]+dr,p[1]+dc)
   ci=next((i for i,cc in enumerate(components) if z in cc),None)
   if ci in marklabels:src[p].add(marklabels[ci])
 # augmented source terminal contributes one degree
 deg={p:sum((p[0]+dr,p[1]+dc) in W for dr,dc in adj)+(1 if src.get(p) else 0) for p in W}
 J={p for p in W if deg[p]!=2};R=W-J;segs=[];U=set(R)
 while U:
  st=next(iter(U));q=[st];U.remove(st);S=set()
  while q:
   p=q.pop();S.add(p)
   for dr,dc in adj:
    z=(p[0]+dr,p[1]+dc)
    if z in U:U.remove(z);q.append(z)
  segs.append(S)
 ends=[]
 for S in segs:
  E=set()
  for p in S:
   for dr,dc in adj:
    z=(p[0]+dr,p[1]+dc)
    if z in J:E.add(z)
  ends.append(E)
 pred={p:wallval for p in W}
 for p,labs in src.items():
  if len(labs)==1:pred[p]=next(iter(labs))
 for S,E in zip(segs,ends):
  labs=set().union(*(src.get(p,set()) for p in S|E))
  if len(labs)==1:
   for p in S:pred[p]=next(iter(labs))
 return pred,W,segs,ends,src,J,deg
